import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;

public class PaymentGateway {

    private static final Map<String, Map<String, Object>> serviceRegistry = new ConcurrentHashMap<>();
    private static final Map<String, Object> defaultServiceConfig = new ConcurrentHashMap<>();
    private static final String HMAC_SECRET = System.getenv("HMAC_SECRET");

    static {
        defaultServiceConfig.put("rateLimit", 1000);
        defaultServiceConfig.put("maxAmount", 10000);
        defaultServiceConfig.put("requireMFA", true);
        defaultServiceConfig.put("allowedOrigins", Arrays.asList("payment-svc", "auth-svc"));
    }

    public static Map<String, Object> getServiceConfig(String serviceId) {
        Map<String, Object> config = serviceRegistry.get(serviceId);
        if (config == null) {
            config = new HashMap<>(defaultServiceConfig);
            serviceRegistry.put(serviceId, config);
        }
        return config;
    }

    public static boolean verifyServiceToken(String serviceId, String token, String timestamp) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            SecretKeySpec keySpec = new SecretKeySpec(
                HMAC_SECRET.getBytes(StandardCharsets.UTF_8), "HmacSHA256");
            mac.init(keySpec);
            String payload = serviceId + ":" + timestamp;
            byte[] computed = mac.doFinal(payload.getBytes(StandardCharsets.UTF_8));
            byte[] provided = Base64.getDecoder().decode(token);
            return MessageDigest.isEqual(computed, provided);
        } catch (Exception e) {
            return false;
        }
    }

    private static boolean isTimestampFresh(String timestamp) {
        try {
            long ts = Long.parseLong(timestamp);
            long now = System.currentTimeMillis() / 1000;
            return Math.abs(now - ts) <= 300;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    public static String processConfigUpdate(Map<String, Object> request) {
        String serviceId = (String) request.get("serviceId");
        String token = (String) request.get("token");
        String timestamp = (String) request.get("timestamp");

        if (serviceId == null || token == null || timestamp == null) {
            return "{\"error\": \"missing required fields\"}";
        }

        if (!isTimestampFresh(timestamp)) {
            return "{\"error\": \"token expired\"}";
        }

        if (!verifyServiceToken(serviceId, token, timestamp)) {
            return "{\"error\": \"authentication failed\"}";
        }

        Map<String, Object> config = getServiceConfig(serviceId);
        Map<String, Object> updates = (Map<String, Object>) request.get("updates");

        if (updates != null) {
            mergeConfig(config, updates);
        }

        return "{\"status\": \"updated\", \"serviceId\": \"" + serviceId + "\"}";
    }

    private static void mergeConfig(Map<String, Object> target, Map<String, Object> source) {
        for (Map.Entry<String, Object> entry : source.entrySet()) {
            String key = entry.getKey();
            Object value = entry.getValue();

            if (key.equals("__proto__") || key.equals("__parent__")) {
                continue;
            } else if (value instanceof Map && target.get(key) instanceof Map) {
                mergeConfig((Map<String, Object>) target.get(key), (Map<String, Object>) value);
            } else {
                target.put(key, value);
            }
        }
    }

    public static String processPayment(Map<String, Object> request) {
        String serviceId = (String) request.get("serviceId");
        String token = (String) request.get("token");
        String timestamp = (String) request.get("timestamp");
        Number amount = (Number) request.get("amount");

        if (serviceId == null || token == null || timestamp == null || amount == null) {
            return "{\"error\": \"missing required fields\"}";
        }

        if (!isTimestampFresh(timestamp)) {
            return "{\"error\": \"token expired\"}";
        }

        if (!verifyServiceToken(serviceId, token, timestamp)) {
            return "{\"error\": \"authentication failed\"}";
        }

        Map<String, Object> config = getServiceConfig(serviceId);

        Boolean requireMFA = (Boolean) config.get("requireMFA");
        if (requireMFA != null && requireMFA) {
            String mfaToken = (String) request.get("mfaToken");
            if (mfaToken == null || !validateMFA(serviceId, mfaToken)) {
                return "{\"error\": \"MFA required\"}";
            }
        }

        Integer maxAmount = (Integer) config.get("maxAmount");
        if (maxAmount != null && amount.intValue() > maxAmount) {
            return "{\"error\": \"amount exceeds limit\"}";
        }

        return executePayment(serviceId, amount.intValue());
    }

    private static boolean validateMFA(String serviceId, String mfaToken) {
        return mfaToken != null && mfaToken.length() == 6 && mfaToken.matches("\\d{6}");
    }

    private static String executePayment(String serviceId, int amount) {
        return "{\"status\": \"success\", \"transactionId\": \"" +
            UUID.randomUUID().toString() + "\", \"amount\": " + amount + "}";
    }
}
